-- tag_description: 태그 설명 지식

SET search_path TO public;

CREATE TABLE IF NOT EXISTS tag_description (
    tag_id                  INTEGER PRIMARY KEY                 ,  -- 태그 정수 키(TAG_INFO.TAG_ID)
    tag_name                VARCHAR(200) NOT NULL               ,  -- 태그명
    description             VARCHAR(500)                        ,  -- 태그 표시용 설명
    tag_nm                  VARCHAR(200)                        ,  -- 태그 원래 이름
    tag_rmk                 VARCHAR(200)                        ,  -- 태그 비고/설비 약칭
    tag_desc                VARCHAR(200)                        ,  -- 태그 부가 표기(계통 등)
    equipment_description   TEXT                                ,  -- 소속 설비 설명
    tag_description         TEXT                                ,  -- 태그가 측정/의미하는 바
    value_change_meaning    TEXT                                ,  -- 값 상승/하강의 의미(원인 해석)
    key_check_points        TEXT                                ,  -- 핵심 점검 항목
    action_guidance         TEXT                                ,  -- 권장 조치 방향
    failure_guidance        TEXT                                ,  -- 장애/트립 대응 지침
    related_tags            JSONB                               ,  -- 관련 태그 목록 [{tag_name, description}]
    content_hash            VARCHAR(64)                         ,  -- 내용 해시(변경 감지)
    created_at              TIMESTAMPTZ NOT NULL DEFAULT NOW()  ,  -- 최초 적재 시각
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT NOW()    -- 최종 수정 시각
);

COMMENT ON TABLE tag_description IS '태그 설명 지식(태그 1:1). LLM 답변 근거';
COMMENT ON COLUMN tag_description.tag_id IS '태그 정수 키(TAG_INFO.TAG_ID)';
COMMENT ON COLUMN tag_description.tag_name IS '태그명';
COMMENT ON COLUMN tag_description.description IS '태그 표시용 설명';
COMMENT ON COLUMN tag_description.tag_nm IS '태그 원래 이름';
COMMENT ON COLUMN tag_description.tag_rmk IS '태그 비고/설비 약칭';
COMMENT ON COLUMN tag_description.tag_desc IS '태그 부가 표기(계통 등)';
COMMENT ON COLUMN tag_description.equipment_description IS '소속 설비 설명';
COMMENT ON COLUMN tag_description.tag_description IS '태그가 측정/의미하는 바';
COMMENT ON COLUMN tag_description.value_change_meaning IS '값 상승/하강의 의미(원인 해석)';
COMMENT ON COLUMN tag_description.key_check_points IS '핵심 점검 항목';
COMMENT ON COLUMN tag_description.action_guidance IS '권장 조치 방향';
COMMENT ON COLUMN tag_description.failure_guidance IS '장애/트립 대응 지침';
COMMENT ON COLUMN tag_description.related_tags IS '관련 태그 목록 [{tag_name, description}]';
COMMENT ON COLUMN tag_description.content_hash IS '내용 해시(변경 감지)';
COMMENT ON COLUMN tag_description.created_at IS '최초 적재 시각';
COMMENT ON COLUMN tag_description.updated_at IS '최종 수정 시각';

CREATE INDEX IF NOT EXISTS idx_tagdesc_tagname ON tag_description(tag_name);

