INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10014460, 'BA_01_1', 'COM01-R01 평균 전압 [플랜트 공통 계통]', 'COM01-R01 평균 전압', 'COM01-R01 평균 전압', '[플랜트 공통 계통]', 'COM01-R01 평균 전압의 전기량 계측 지점으로, 플랜트 공통 계통의 전력/전류/전압을 감시합니다.', '전력/전류/전압을 측정하여 설비 부하와 전기 상태를 판단하는 지표입니다.', '상승: 부하 급증·역률/전압 변동. 하강: 부하 급감·기기 정지 또는 전원 이상.', '1. 전기량 추세와 부하 상태 확인. 2. 관련 설비 운전 상태 확인. 3. 전원·계측 정상 여부 확인.', '부하·전원 상태를 확인하고 필요 시 부하를 조정, 전기 담당에 통보.', '이상 지속 시 관련 전기설비 보호 동작 여부를 확인하고 계통 영향 최소화.', '[{"tag_name": "BA_01_2", "description": "COM01-R01 평균 전류"}, {"tag_name": "BA_01_3", "description": "COM01-R01 R상 전류"}, {"tag_name": "BA_01_4", "description": "COM01-R01 S상 전류"}, {"tag_name": "BA_01_5", "description": "COM01-R01 T상 전류"}, {"tag_name": "BA_01_6", "description": "COM01-R01 역률"}, {"tag_name": "BA_01_7", "description": "COM01-R01 순시 전력"}, {"tag_name": "BA_01_8", "description": "COM01-R01 유효전력량(적산)"}, {"tag_name": "BA_03_1", "description": "COM01-R02 평균 전압"}]'::jsonb, 'c35cc664bb78f563438c32b5bb14b45fb1ac1139c788b582236effc125db4f9a') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
