INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10011287, 'BDFAN-401R', 'FD Fan Run [보일러 계통]', 'FD Fan Run', 'FD Fan Run', '[보일러 계통]', 'FD Fan Run의 상태 감시 지점으로, 개폐·기동정지·트립 등 설비 상태를 감시합니다.', '설비의 운전 상태(개도·기동/정지·트립 등)를 나타내는 상태 지표입니다.', '상태 변화(알람): 제어 신호·인터록 동작, 액추에이터·리밋스위치 이상, 전원·구동부 이상 또는 현장 수동 조작.', '1. 현장 상태(개도·기동/정지) 확인. 2. 제어 신호·인터록 조건 확인. 3. 액추에이터·리밋스위치·전원 상태 확인.', '현장 상태와 제어 신호를 확인하고 인터록·구동부를 점검. 이상 지속 시 관련 계통 영향 확인 후 보고.', '예상치 못한 트립/차단 시 관련 계통 안전 상태를 확보하고 원인 규명 전까지 재기동을 보류.', '[]'::jsonb, '6344d499ef35a5ea1d726c370169ebc1effcffa7e2196b268ab85c1247f82279') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10012080, 'BDFCD-401', 'FD Fan Output [보일러 계통]', 'FD Fan Output', 'FD Fan Output', '[보일러 계통]', 'FD Fan Output의 계측 지점으로, 보일러 계통의 공정 상태를 감시합니다.', '공정 측정값으로, 관련 계통의 상태 변화를 판단하는 지표입니다.', '상승: 공정 조건 변화(부하·수요) 또는 관련 기기·밸브 이상. 하강: 공급 부족·누설 또는 기기 성능 저하. 급변 시 계측 이상 가능.', '1. 측정값 현재값·추세 확인. 2. 관련 태그와 교차 확인. 3. 관련 기기·밸브 상태 확인.', '측정값 추세와 관련 기기 상태를 확인하고 필요한 조치를 취하며, 계측 이상 시 교차 검증.', '상·하한 이탈 지속 시 관련 계통 영향을 확인하고 담당자에 보고, 필요 시 예비 기기 절체.', '[]'::jsonb, '23b70fa9a533162741c7c28a210d756b624373bd3491bd82cef018d6cb5f6d13') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
