INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10012137, 'BDTCD-820-FB', 'SCR By-pass Damper Feed Back [보일러 계통]', 'SCR By-pass Damper Feed Back', 'SCR By-pass Damper Feed Back', '[보일러 계통]', 'SCR By-pass Damper Feed Back의 계측 지점으로, 보일러 계통의 공정 상태를 감시합니다.', '공정 측정값으로, 관련 계통의 상태 변화를 판단하는 지표입니다.', '상승: 공정 조건 변화(부하·수요) 또는 관련 기기·밸브 이상. 하강: 공급 부족·누설 또는 기기 성능 저하. 급변 시 계측 이상 가능.', '1. 측정값 현재값·추세 확인. 2. 관련 태그와 교차 확인. 3. 관련 기기·밸브 상태 확인.', '측정값 추세와 관련 기기 상태를 확인하고 필요한 조치를 취하며, 계측 이상 시 교차 검증.', '상·하한 이탈 지속 시 관련 계통 영향을 확인하고 담당자에 보고, 필요 시 예비 기기 절체.', '[{"tag_name": "BDTCD-820-O", "description": "SCR By-pass Damper Open"}, {"tag_name": "BDTCD-820-RE", "description": "SCR By-pass Damper Remote"}, {"tag_name": "BDTCD-821-FB", "description": "SCR Main Damper Feed Back"}, {"tag_name": "BDTCD-821-O", "description": "SCA Main Damper Open"}, {"tag_name": "BDTCD-821-RE", "description": "SCR Main Damper Remote"}]'::jsonb, '374c54e51e58bdfefc53fe3e374dfb35de859fc8b533fef1d19d521323117f16') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
