INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10011292, 'BDTE-802F', 'Stack Gas Temp [보일러 계통]', 'Stack Gas Temp', 'Stack Gas Temp', '[보일러 계통]', 'Stack Gas Temp의 연소·배가스 분석 지점으로, 연소 효율과 배출가스 상태를 감시합니다.', '연소 지표(O2/NOx/CO 등)를 측정하여 공기-연료비와 배출가스 상태를 판단하는 지표입니다.', '상승: 과잉 공기 유입 또는 부하 변동에 따른 연소 조건 변화. 하강: 공기 공급 부족으로 인한 미연분(CO) 발생 위험 및 연소 효율 저하.', '1. 연소 지표 추세와 부하·공기비 확인. 2. 송풍기·댐퍼 상태 확인. 3. 분석기 프로브 오염·샘플링 라인 누설 확인.', '공기비 제어 모드와 송풍기·댐퍼를 점검하여 공기-연료비를 조정하고, 분석기 이상 시 교정.', 'O2 급저하 시 미연분·화염 상태를 집중 감시하고 연료차단(MFT) 조건에 유의. 배출 규제 초과 시 즉시 연소 조정.', '[{"tag_name": "BDTE-101A", "description": "Metal Temp Top (Left)"}, {"tag_name": "BDTE-101B", "description": "Metal Temp Top (Right)"}, {"tag_name": "BDTE-101C", "description": "Metal Temp Bottom (Left)"}, {"tag_name": "BDTE-101D", "description": "Metal Temp Bottom (Right)"}, {"tag_name": "BDTE-103", "description": "Pri S/H Outlet STM Temp"}, {"tag_name": "BDTE-106", "description": "SEC. S/H Outlet Temp"}, {"tag_name": "BDTE-107", "description": "Temp S/H Inlet Temp"}, {"tag_name": "BDTE-109", "description": "Main STM Temp"}]'::jsonb, '38c393fef24b529fcf3ffc6587a531813d064d6065522dcb6cfff841bee8d261') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
