INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10014562, 'CA_01_1', 'COM03-R40 순시 전력 [플랜트 공통 계통]', 'COM03-R40 순시 전력', 'COM03-R40 순시 전력', '[플랜트 공통 계통]', 'COM03-R40 순시 전력의 전기량 계측 지점으로, 플랜트 공통 계통의 전력/전류/전압을 감시합니다.', '전력/전류/전압을 측정하여 설비 부하와 전기 상태를 판단하는 지표입니다.', '상승: 부하 급증·역률/전압 변동. 하강: 부하 급감·기기 정지 또는 전원 이상.', '1. 전기량 추세와 부하 상태 확인. 2. 관련 설비 운전 상태 확인. 3. 전원·계측 정상 여부 확인.', '부하·전원 상태를 확인하고 필요 시 부하를 조정, 전기 담당에 통보.', '이상 지속 시 관련 전기설비 보호 동작 여부를 확인하고 계통 영향 최소화.', '[{"tag_name": "CA_01_2", "description": "COM03-R40 유효전력량(적산)"}, {"tag_name": "CA_10_1", "description": "COM04-R51 순시 전력"}, {"tag_name": "CA_10_2", "description": "COM04-R51 유효전력량(적산)"}, {"tag_name": "CA_14_1", "description": "COM03-R42 순시 전력"}, {"tag_name": "CA_14_2", "description": "COM03-R42 유효전력량(적산)"}, {"tag_name": "CA_24_1", "description": "COM03-R47 순시 전력"}, {"tag_name": "CA_24_2", "description": "COM03-R47 유효전력량(적산)"}, {"tag_name": "CA_30_1", "description": "COM03-R46 순시 전력"}]'::jsonb, 'bfa94fd80caf9d3b9919d70dad385b3de66599032bcbfa2364e5a1d5e3bf6955') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10014563, 'CA_01_2', 'COM03-R40 유효전력량(적산) [플랜트 공통 계통]', 'COM03-R40 유효전력량(적산)', 'COM03-R40 유효전력량(적산)', '[플랜트 공통 계통]', 'COM03-R40 유효전력량(적산)의 적산 계량 지점으로, 공급된 유량/열량의 누적값을 관리합니다.', '적산(유량/열량) 계량값으로, 수요처 공급량 정산과 계량 건전성 판단에 사용됩니다.', '정상 시 단조 증가. 급변·정지: 계량기 오차·펄스 누락, 역류/기포/이물질, 통신 지연에 따른 적산 누락 가능.', '1. 적산값 추세와 순시(유량/온도) 값 정합성 확인. 2. 계량기·통신 상태 확인. 3. 역류·기포·이물질 여부 확인.', '적산-순시 값 대조로 정합성 확인, 계량기/통신 점검. 이상 지속 시 계량 정비 담당 통보 및 대체 계량 검토.', '계량 정지·역행 발생 시 정산 영향 최소화를 위해 즉시 대체 계량 및 보정 절차 적용.', '[{"tag_name": "CA_01_1", "description": "COM03-R40 순시 전력"}, {"tag_name": "CA_10_1", "description": "COM04-R51 순시 전력"}, {"tag_name": "CA_10_2", "description": "COM04-R51 유효전력량(적산)"}, {"tag_name": "CA_14_1", "description": "COM03-R42 순시 전력"}, {"tag_name": "CA_14_2", "description": "COM03-R42 유효전력량(적산)"}, {"tag_name": "CA_24_1", "description": "COM03-R47 순시 전력"}, {"tag_name": "CA_24_2", "description": "COM03-R47 유효전력량(적산)"}, {"tag_name": "CA_30_1", "description": "COM03-R46 순시 전력"}]'::jsonb, 'eda35937cf5d0f95d28381160da49be2aa9ef5c8c37a96965a6ac977c0f84a92') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
