INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10012349, 'CBZT-401', 'FD Fan Feed Back [급수 계통]', 'FD Fan Feed Back', 'FD Fan Feed Back', '[급수 계통]', 'FD Fan Feed Back의 계측 지점으로, 급수 계통의 공정 상태를 감시합니다.', '공정 측정값으로, 관련 계통의 상태 변화를 판단하는 지표입니다.', '상승: 공정 조건 변화(부하·수요) 또는 관련 기기·밸브 이상. 하강: 공급 부족·누설 또는 기기 성능 저하. 급변 시 계측 이상 가능.', '1. 측정값 현재값·추세 확인. 2. 관련 태그와 교차 확인. 3. 관련 기기·밸브 상태 확인.', '측정값 추세와 관련 기기 상태를 확인하고 필요한 조치를 취하며, 계측 이상 시 교차 검증.', '상·하한 이탈 지속 시 관련 계통 영향을 확인하고 담당자에 보고, 필요 시 예비 기기 절체.', '[{"tag_name": "CBZT-102", "description": "STM Vent MOV Feed Back"}, {"tag_name": "CBZT-251", "description": "BLR Drain MOV Feed Back"}]'::jsonb, '2357d28907a46173431de9cc52f1e16d7ef2effcad471adb9dd98d697ec649ff') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10011345, 'CCAIT-801', 'Fuel Gas O2 [연소·배가스 계통]', 'Fuel Gas O2', 'Fuel Gas O2', '[연소·배가스 계통]', 'Fuel Gas O2의 연소·배가스 분석 지점으로, 연소 효율과 배출가스 상태를 감시합니다.', '연소 지표(O2/NOx/CO 등)를 측정하여 공기-연료비와 배출가스 상태를 판단하는 지표입니다.', '상승: 과잉 공기 유입 또는 부하 변동에 따른 연소 조건 변화. 하강: 공기 공급 부족으로 인한 미연분(CO) 발생 위험 및 연소 효율 저하.', '1. 연소 지표 추세와 부하·공기비 확인. 2. 송풍기·댐퍼 상태 확인. 3. 분석기 프로브 오염·샘플링 라인 누설 확인.', '공기비 제어 모드와 송풍기·댐퍼를 점검하여 공기-연료비를 조정하고, 분석기 이상 시 교정.', 'O2 급저하 시 미연분·화염 상태를 집중 감시하고 연료차단(MFT) 조건에 유의. 배출 규제 초과 시 즉시 연소 조정.', '[{"tag_name": "CCAIT-802A", "description": "Stack Gas O2"}, {"tag_name": "CCAIT-802B", "description": "Stack Gas Nox"}, {"tag_name": "CCAIT-802C", "description": "Stack Gas Sox"}, {"tag_name": "CCAIT-802E", "description": "Stack Gas Dust"}, {"tag_name": "CCAIT-803", "description": "#2 SCR Gas Inlet Nox"}, {"tag_name": "CCAIT-803C", "description": "Stack Gas Nox"}, {"tag_name": "CCAIT-804", "description": "#2 SCR Gas Inlet O2"}, {"tag_name": "CCAIT-805", "description": "#2 SCR Gas Outlet Nox"}]'::jsonb, 'e177d22485c2b71205f44baa9ca854130a66182607cb29b65cfc366b80a2287f') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
