INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10014636, 'DA_TI_940', 'CV-CHEST TEMP. INSIDE TURBINE [터빈·발전기 계통]', 'CV-CHEST TEMP. INSIDE TURBINE', 'CV-CHEST TEMP. INSIDE TURBINE', '[터빈·발전기 계통]', 'CV-CHEST TEMP. INSIDE TURBINE의 온도 계측 지점으로, 터빈·발전기 계통의 열공급/회수 온도 상태를 감시합니다.', '열원 공급과 열교환 상태를 판단하는 온도 지표입니다.', '상승: 열원 과열·온도 제어 이상 또는 부하 급감에 따른 공급열 과잉. 하강: 열원 공급 부족·열교환기 성능 저하 또는 부하 급증.', '1. 온도 현재값·추세 확인. 2. 열원(보일러/열교환기) 운전 상태 확인. 3. 부하 변동 확인. 4. 온도 발신기 정상 여부 확인.', '열원 공급과 열교환 상태를 확인하고 제어 모드·설정값을 점검하여 열공급을 조정.', '온도 과상승 지속 시 열원 출력 경감 및 관련 계통 보호 조치. 과저하 시 공급 부족 원인을 우선 조치.', '[{"tag_name": "DA_TI_941", "description": "CASING TEMP. TURBINE FREE RANGE"}, {"tag_name": "DA_TI_941A", "description": "CASING TEMP. TURBINE TOP"}, {"tag_name": "DA_TI_941B", "description": "CASING TEMP. TURBINE BOTTOM"}, {"tag_name": "DA_TI_942", "description": "FLANGE TEMP. TURBINE FREE RANGE"}, {"tag_name": "DA_TI_942A", "description": "CASING TEMP. TURBINE FLANGE INSIDE"}, {"tag_name": "DA_TI_942B", "description": "CASING TEMP. TURBINE FLANGE MIDDLE"}, {"tag_name": "DA_TI_960", "description": "BMT. RADIAL BEARING GENO REAR"}, {"tag_name": "DA_TI_961", "description": "BMT. RADIAL BEARING GENO FRONT"}]'::jsonb, '9dd6dca46f2a7e535ea831296678afecfb8dd6392b0f7ca1c3a67752148864fa') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
