INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10014664, 'DA_YI_900A', 'PEDESTAL VIBRATION GENO REAR X [터빈·발전기 계통]', 'PEDESTAL VIBRATION GENO REAR X', 'PEDESTAL VIBRATION GENO REAR X', '[터빈·발전기 계통]', 'PEDESTAL VIBRATION GENO REAR X의 진동/베어링 감시 지점으로, 회전기기 건전성을 감시합니다.', '진동 또는 베어링 온도를 측정하여 회전기기의 이상 징후를 판단하는 지표입니다.', '상승: 축 정렬 불량·불평형, 베어링 윤활 이상·마모, 부하 변동·공진 등에 의한 진동/발열 증가.', '1. 진동·베어링 온도 추세와 급변 확인. 2. 윤활유 압력·온도·수위 및 오일 상태 확인. 3. 이상음·발열 현장 확인.', '윤활 상태와 진동 추세를 확인하고 필요 시 부하를 경감. 급변 시 정지 절차 및 정비 담당 통보 검토.', '진동/베어링 온도 급상승 지속 시 회전기기 보호를 위해 정지 절차를 신속히 검토.', '[{"tag_name": "DA_YI_900B", "description": "PEDESTAL VIBRATION GENO REAR Y"}, {"tag_name": "DA_YI_901A", "description": "PEDESTAL VIBRATION GENO FRONT X"}, {"tag_name": "DA_YI_901B", "description": "PEDESTAL VIBRATION GENO FRONT Y"}, {"tag_name": "DA_YI_902", "description": "SHAFT VIBRATION TURBINE G50LP X"}, {"tag_name": "DA_YI_903", "description": "SHAFT VIBRATION TURBINE G50HP X"}, {"tag_name": "DA_YI_904", "description": "SHAFT VIBRATION TURBINE VE63HP X"}, {"tag_name": "DA_YI_905", "description": "SHAFT VIBRATION TURBINE VE63LP X"}, {"tag_name": "DA_YI_960", "description": "RELATIVE EXPANSION G50"}]'::jsonb, '0830b6ba7bb145856ea76d9de5c476f7930062562fbe444378136dfe04573b40') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
