INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10014738, 'DF_PI_111A', 'STEAM PRESSURE BLEEDING 1 [플랜트 공통 계통]', 'STEAM PRESSURE BLEEDING 1', 'STEAM PRESSURE BLEEDING 1', '[플랜트 공통 계통]', 'STEAM PRESSURE BLEEDING 1의 압력 계측 지점으로, 플랜트 공통 계통의 압력 상태와 순환/공급 균형을 감시합니다.', '계통 압력을 측정하여 순환 상태와 부하 변화를 판단하는 핵심 지표입니다.', '상승: 부하측 밸브 급폐·수요 급감 또는 배관 저항 증가에 따른 압력 상승. 하강: 순환수 누설·펌프 성능 저하·흡입측 막힘에 따른 압력 저하.', '1. 압력 현재값·추세 확인. 2. 공급/회수 압력·차압 균형 확인. 3. 관련 펌프·밸브 상태 확인. 4. 통신상태(계측 신뢰성) 확인.', '부하측 밸브·수요 변화 확인 후 순환유량/개도를 단계적으로 조정. 펌프 제어 모드와 인버터·바이패스 상태 점검. 미해소 시 예비 펌프 절체 검토.', '고압 지속 시 부하 경감 후 정지 절차 검토(트립 예방). 저압 급강 시 저압 트립·공동현상에 유의하고 급수/보충수 계통을 회복.', '[{"tag_name": "DF_PI_111B", "description": "STEAM PRESSURE BLEEDING 2"}, {"tag_name": "DF_PI_111C", "description": "STEAM PRESSURE EXTRACTION"}, {"tag_name": "DF_PI_111D", "description": "STEAM PRESSURE BLEEDING 3"}, {"tag_name": "DF_PI_191", "description": "EXHAUST STEAM PRESSURE"}, {"tag_name": "DF_PI_192", "description": "STEAM PRESSURE EXTRACTION CLC"}, {"tag_name": "DF_PI_194", "description": "WHEEL CHAMBER PRESSURE"}, {"tag_name": "DF_PI_197", "description": "WHEEL CHAMBER PRESSURE LP FIRST STAGE"}]'::jsonb, '736c3ba47615f7c4dee20a023460e989091bc13b9fce436a91b3de8b8b7d51d4') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
