INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10011559, 'EETE-203', '순환수 후단 Temp [플랜트 공통 계통]', '순환수 후단 Temp', '순환수 후단 Temp', '[플랜트 공통 계통]', '순환수 후단 Temp의 온도 계측 지점으로, 플랜트 공통 계통의 열공급/회수 온도 상태를 감시합니다.', '열원 공급과 열교환 상태를 판단하는 온도 지표입니다.', '상승: 열원 과열·온도 제어 이상 또는 부하 급감에 따른 공급열 과잉. 하강: 열원 공급 부족·열교환기 성능 저하 또는 부하 급증.', '1. 온도 현재값·추세 확인. 2. 열원(보일러/열교환기) 운전 상태 확인. 3. 부하 변동 확인. 4. 온도 발신기 정상 여부 확인.', '열원 공급과 열교환 상태를 확인하고 제어 모드·설정값을 점검하여 열공급을 조정.', '온도 과상승 지속 시 열원 출력 경감 및 관련 계통 보호 조치. 과저하 시 공급 부족 원인을 우선 조치.', '[{"tag_name": "EETE-206A", "description": "ConInlet Cooling WTR Temp"}, {"tag_name": "EETE-206B", "description": "ConInlet Cooling WTR Temp"}, {"tag_name": "EETE-207A", "description": "Con Outlet Cooling WTR Temp"}, {"tag_name": "EETE-207B", "description": "Con Outlet Cooling WTR Temp"}, {"tag_name": "EETE-208", "description": "Waste WTR Temp"}, {"tag_name": "EETE-209", "description": "냉각탑 Temp"}, {"tag_name": "EETE-213", "description": "냉각수 후단 Temp"}, {"tag_name": "EETE-225A", "description": "TBN L.O Cooling WTR Inlet Temp"}]'::jsonb, '9da6f7e5eb80c643cac9c32d6be1da937cab75d8f64418e0998cc821b3d64b9f') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
