INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10011589, 'EKMOV-242O', 'EKMOV-242 Open [열교환기 계통]', 'EKMOV-242 Open', 'EKMOV-242 Open', '[열교환기 계통]', 'EKMOV-242 Open의 상태 감시 지점으로, 개폐·기동정지·트립 등 설비 상태를 감시합니다.', '설비의 운전 상태(개도·기동/정지·트립 등)를 나타내는 상태 지표입니다.', '상태 변화(알람): 제어 신호·인터록 동작, 액추에이터·리밋스위치 이상, 전원·구동부 이상 또는 현장 수동 조작.', '1. 현장 상태(개도·기동/정지) 확인. 2. 제어 신호·인터록 조건 확인. 3. 액추에이터·리밋스위치·전원 상태 확인.', '현장 상태와 제어 신호를 확인하고 인터록·구동부를 점검. 이상 지속 시 관련 계통 영향 확인 후 보고.', '예상치 못한 트립/차단 시 관련 계통 안전 상태를 확보하고 원인 규명 전까지 재기동을 보류.', '[{"tag_name": "EKMOV-251", "description": "동양환경 F.W MOV Open"}]'::jsonb, '351514a1e1cb23108627add3d20def6876602d8770e9e5a84463e2e7bef69e74') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
