INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (19000051, 'M001', '용폐수검침(적산량)-공업용수 [플랜트 공통 계통]', '용폐수검침(적산량)-공업용수', '용폐수검침(적산량)-공업용수', '[플랜트 공통 계통]', '용폐수검침(적산량)-공업용수의 적산 계량 지점으로, 공급된 유량/열량의 누적값을 관리합니다.', '적산(유량/열량) 계량값으로, 수요처 공급량 정산과 계량 건전성 판단에 사용됩니다.', '정상 시 단조 증가. 급변·정지: 계량기 오차·펄스 누락, 역류/기포/이물질, 통신 지연에 따른 적산 누락 가능.', '1. 적산값 추세와 순시(유량/온도) 값 정합성 확인. 2. 계량기·통신 상태 확인. 3. 역류·기포·이물질 여부 확인.', '적산-순시 값 대조로 정합성 확인, 계량기/통신 점검. 이상 지속 시 계량 정비 담당 통보 및 대체 계량 검토.', '계량 정지·역행 발생 시 정산 영향 최소화를 위해 즉시 대체 계량 및 보정 절차 적용.', '[{"tag_name": "M002", "description": "용폐수검침(적산량)-생활용수"}, {"tag_name": "M003", "description": "용폐수검침(적산량)-도시공사"}, {"tag_name": "M004", "description": "용폐수검침(적산량)-순수생산량"}, {"tag_name": "M005", "description": "용폐수검침(적산량)-폐수방류량"}, {"tag_name": "M006", "description": "지역난방-보충수적산량"}, {"tag_name": "M007", "description": "전력판매-MP"}, {"tag_name": "M008", "description": "전력판매-CP1"}, {"tag_name": "M009", "description": "전력판매-CP2"}]'::jsonb, '28dcd6956f98de7275a2e1e9b50f433fcd554a6313f90e06fff3746542defa81') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
