INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (19000074, 'M020', '발전량(적삭) MWh [플랜트 공통 계통]', '발전량(적삭) MWh', '발전량(적삭) MWh', '[플랜트 공통 계통]', '발전량(적삭) MWh의 계측 지점으로, 플랜트 공통 계통의 공정 상태를 감시합니다.', '공정 측정값으로, 관련 계통의 상태 변화를 판단하는 지표입니다.', '상승: 공정 조건 변화(부하·수요) 또는 관련 기기·밸브 이상. 하강: 공급 부족·누설 또는 기기 성능 저하. 급변 시 계측 이상 가능.', '1. 측정값 현재값·추세 확인. 2. 관련 태그와 교차 확인. 3. 관련 기기·밸브 상태 확인.', '측정값 추세와 관련 기기 상태를 확인하고 필요한 조치를 취하며, 계측 이상 시 교차 검증.', '상·하한 이탈 지속 시 관련 계통 영향을 확인하고 담당자에 보고, 필요 시 예비 기기 절체.', '[{"tag_name": "M001", "description": "용폐수검침(적산량)-공업용수"}, {"tag_name": "M002", "description": "용폐수검침(적산량)-생활용수"}, {"tag_name": "M003", "description": "용폐수검침(적산량)-도시공사"}, {"tag_name": "M004", "description": "용폐수검침(적산량)-순수생산량"}, {"tag_name": "M005", "description": "용폐수검침(적산량)-폐수방류량"}, {"tag_name": "M006", "description": "지역난방-보충수적산량"}, {"tag_name": "M007", "description": "전력판매-MP"}, {"tag_name": "M008", "description": "전력판매-CP1"}]'::jsonb, '780ef17ebdfa04a35e41789bd2b571e5b98451b1ebad1b94c349e2211e7c6ad6') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
