INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10014783, 'MAA10CF910', 'EXHAUST STEAM FLOW [플랜트 공통 계통]', 'EXHAUST STEAM FLOW', 'EXHAUST STEAM FLOW', '[플랜트 공통 계통]', 'EXHAUST STEAM FLOW의 유량 계측 지점으로, 플랜트 공통 계통의 순환/공급 유량을 감시합니다.', '계통 순환/공급 유량을 측정하여 수요 대응과 배관 상태를 판단하는 지표입니다.', '상승: 수요 급증 또는 제어밸브 과개도. 하강: 수요 급감·밸브 막힘·펌프 성능 저하 또는 배관 누설.', '1. 유량 현재값·추세 확인. 2. 수요·밸브 개도 확인. 3. 펌프 상태 확인. 4. 유량계 정상 여부 확인.', '수요·밸브 상태 확인 후 유로를 조정하고, 유량계 이상 시 교차 확인.', '유량 급감 지속 시 펌프·배관 막힘/누설 여부를 우선 점검하고 필요 시 유로 절체.', '[{"tag_name": "MAA10CG310", "description": "FB ESV HP1 LIVE STEAM OPEN"}, {"tag_name": "MAA10CG311", "description": "FB ESV HP1 LIVE STEAM CLOSE -TURBINE TRIP"}, {"tag_name": "MAA10CG320", "description": "FB ESV HP2 LIVE STEAM OPEN"}, {"tag_name": "MAA10CG321", "description": "FB ESV HP2 LIVE STEAM CLOSE -TURBINE TRIP"}, {"tag_name": "MAA10CG910zm02", "description": "AXIAL SHAFT POSITION 2oo3"}, {"tag_name": "MAA10CS910XH55zm02", "description": "SPEED TURBINE 2oo3 < 300 RPM"}, {"tag_name": "MAA10CS910XH56", "description": "SPEED TURBINE 2oo3 < 4 RPM"}, {"tag_name": "MAA10CS911", "description": "SPEED GENERATOR 2oo3"}]'::jsonb, 'a6e7d340ba0aa69abdcf9259bd63215e8d210e14f8c44e8c0bb442f0d644cafc') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
