INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (13002392, 'RC039', '원유 온도보정계수 API54B (RC039) [플랜트 공통 계통]', '원유 온도보정계수 API54B (RC039)', '원유 온도보정계수 API54B (RC039)', '[플랜트 공통 계통]', '원유 온도보정계수 API54B (RC039)의 온도 계측 지점으로, 플랜트 공통 계통의 열공급/회수 온도 상태를 감시합니다.', '열원 공급과 열교환 상태를 판단하는 온도 지표입니다.', '상승: 열원 과열·온도 제어 이상 또는 부하 급감에 따른 공급열 과잉. 하강: 열원 공급 부족·열교환기 성능 저하 또는 부하 급증.', '1. 온도 현재값·추세 확인. 2. 열원(보일러/열교환기) 운전 상태 확인. 3. 부하 변동 확인. 4. 온도 발신기 정상 여부 확인.', '열원 공급과 열교환 상태를 확인하고 제어 모드·설정값을 점검하여 열공급을 조정.', '온도 과상승 지속 시 열원 출력 경감 및 관련 계통 보호 조치. 과저하 시 공급 부족 원인을 우선 조치.', '[{"tag_name": "RC142", "description": "LPG 소형탱크 용적 (RC142)"}, {"tag_name": "RC143", "description": "LPG 대형탱크 용적 (RC143)"}, {"tag_name": "RC144", "description": "LPG 대형탱크 용적 (RC144)"}, {"tag_name": "RC145", "description": "LPG 대형탱크 용적 (RC145)"}, {"tag_name": "RC146", "description": "LPG 대형탱크 용적 (RC146)"}, {"tag_name": "RC147", "description": "LPG 소형탱크 용적 (RC147)"}, {"tag_name": "RC148", "description": "LPG 밀도 (RC148)"}, {"tag_name": "RC149", "description": "LPG 밀도 (RC149)"}]'::jsonb, '05be7a65f06686f85123856d499504436cc01f555e091839b8038064c9e2185c') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (13002393, 'RC142', 'LPG 소형탱크 용적 (RC142) [연료가스 계통]', 'LPG 소형탱크 용적 (RC142)', 'LPG 소형탱크 용적 (RC142)', '[연료가스 계통]', 'LPG 소형탱크 용적 (RC142)의 계측 지점으로, 연료가스 계통의 공정 상태를 감시합니다.', '공정 측정값으로, 관련 계통의 상태 변화를 판단하는 지표입니다.', '상승: 공정 조건 변화(부하·수요) 또는 관련 기기·밸브 이상. 하강: 공급 부족·누설 또는 기기 성능 저하. 급변 시 계측 이상 가능.', '1. 측정값 현재값·추세 확인. 2. 관련 태그와 교차 확인. 3. 관련 기기·밸브 상태 확인.', '측정값 추세와 관련 기기 상태를 확인하고 필요한 조치를 취하며, 계측 이상 시 교차 검증.', '상·하한 이탈 지속 시 관련 계통 영향을 확인하고 담당자에 보고, 필요 시 예비 기기 절체.', '[{"tag_name": "RC039", "description": "원유 온도보정계수 API54B (RC039)"}, {"tag_name": "RC143", "description": "LPG 대형탱크 용적 (RC143)"}, {"tag_name": "RC144", "description": "LPG 대형탱크 용적 (RC144)"}, {"tag_name": "RC145", "description": "LPG 대형탱크 용적 (RC145)"}, {"tag_name": "RC146", "description": "LPG 대형탱크 용적 (RC146)"}, {"tag_name": "RC147", "description": "LPG 소형탱크 용적 (RC147)"}, {"tag_name": "RC148", "description": "LPG 밀도 (RC148)"}, {"tag_name": "RC149", "description": "LPG 밀도 (RC149)"}]'::jsonb, '588d1c1a692b14733d0326625d8e236d8a9b7e197aec93ab55dc95d8024bb729') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
