INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10010346, 'RPU_15_17_W_A3', '크라운제과 - 유량 [지역난방 수요처 공급계통]', '크라운제과 - 유량', '크라운제과', '[지역난방 수요처 공급계통]', '크라운제과의 유량 계측 지점으로, 지역난방 수요처 공급계통의 순환/공급 유량을 감시합니다.', '계통 순환/공급 유량을 측정하여 수요 대응과 배관 상태를 판단하는 지표입니다.', '상승: 수요 급증 또는 제어밸브 과개도. 하강: 수요 급감·밸브 막힘·펌프 성능 저하 또는 배관 누설.', '1. 유량 현재값·추세 확인. 2. 수요·밸브 개도 확인. 3. 펌프 상태 확인. 4. 유량계 정상 여부 확인.', '수요·밸브 상태 확인 후 유로를 조정하고, 유량계 이상 시 교차 확인.', '유량 급감 지속 시 펌프·배관 막힘/누설 여부를 우선 점검하고 필요 시 유로 절체.', '[{"tag_name": "MM_RPU_15_17_A4", "description": "크라운제과 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_15_17_A5", "description": "크라운제과 - 적산열량 (DIFF)"}, {"tag_name": "MM_RPU_15_17_W_A4", "description": "크라운제과 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_15_17_W_A5", "description": "크라운제과 - 적산열량 (DIFF)"}, {"tag_name": "RPU_15_17_A1", "description": "크라운제과 - 공급온도"}, {"tag_name": "RPU_15_17_A2", "description": "크라운제과 - 회수온도"}, {"tag_name": "RPU_15_17_A3", "description": "크라운제과 - 유량"}, {"tag_name": "RPU_15_17_A4", "description": "크라운제과 - 적산유량"}]'::jsonb, '698d784c25b564e941c71f9f8af27ab4da197d20df17bf92238c1c7a7147518c') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
