INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (20010059, 'RPU_15_23_STS', '진합 - 통신상태 [지역난방 수요처 공급계통]', '진합 - 통신상태', '진합', '[지역난방 수요처 공급계통]', '진합의 통신 상태 감시 지점으로, 원격 계측(RPU)의 통신 건전성을 감시합니다.', '계측기 통신 상태를 나타내며, 값 신뢰성 판단의 기준이 됩니다.', '통신 두절(알람): RPU/네트워크 장애, 케이블·전원 이상, 현장 계측기 고장 또는 상위 수집 서버 장애.', '1. 통신 선로·전원 상태 확인. 2. RPU·게이트웨이 동작 상태 확인. 3. 해당 설비 계측값 신뢰성 교차 확인.', '통신 선로·전원과 RPU 상태를 확인하고 재접속·리셋. 미복구 시 계측 정비 담당에 통보.', '통신 두절 동안 해당 설비 계측값을 신뢰성 주의로 간주하고 관련 태그로 교차 판단.', '[{"tag_name": "MM_RPU_15_23_A4", "description": "진합 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_15_23_A5", "description": "진합 - 적산열량 (DIFF)"}, {"tag_name": "RPU_15_23_A1", "description": "진합 - 공급온도"}, {"tag_name": "RPU_15_23_A2", "description": "진합 - 회수온도"}, {"tag_name": "RPU_15_23_A3", "description": "진합 - 유량"}, {"tag_name": "RPU_15_23_A4", "description": "진합 - 적산유량"}, {"tag_name": "RPU_15_23_A5", "description": "진합 - 적산열량"}, {"tag_name": "RPU_15_23_A6", "description": "진합 - 압력"}]'::jsonb, '94a27819d3f77f8297f3af435a8e450a2730898a0cff695bab467537aac626c1') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (13000002, 'RPU_15_A3_SUM', '15ATA 공정용 증기 총합 [지역난방 수요처 공급계통]', '15ATA 공정용 증기 총합', '15ATA 공정용 증기 총합', '[지역난방 수요처 공급계통]', '15ATA 공정용 증기 총합의 유량 계측 지점으로, 지역난방 수요처 공급계통의 순환/공급 유량을 감시합니다.', '계통 순환/공급 유량을 측정하여 수요 대응과 배관 상태를 판단하는 지표입니다.', '상승: 수요 급증 또는 제어밸브 과개도. 하강: 수요 급감·밸브 막힘·펌프 성능 저하 또는 배관 누설.', '1. 유량 현재값·추세 확인. 2. 수요·밸브 개도 확인. 3. 펌프 상태 확인. 4. 유량계 정상 여부 확인.', '수요·밸브 상태 확인 후 유로를 조정하고, 유량계 이상 시 교차 확인.', '유량 급감 지속 시 펌프·배관 막힘/누설 여부를 우선 점검하고 필요 시 유로 절체.', '[{"tag_name": "RPU_15_18_A3_SUM", "description": "동양환경 증기 총합"}, {"tag_name": "RPU_15_W_A3_SUM", "description": "15ATA 공정용 응축수 총합"}, {"tag_name": "RPU_30_99_A1", "description": "-"}, {"tag_name": "RPU_30_99_A2", "description": "-"}, {"tag_name": "RPU_30_99_A5", "description": "-"}, {"tag_name": "RPU_30_99_A6", "description": "-"}, {"tag_name": "RPU_30_99_A7", "description": "-"}, {"tag_name": "RPU_9_09_D_A1", "description": "D/H PIPE OUTLET TEMP"}]'::jsonb, '8789b385071a0ccef114fd377eeef7e72ee6c2b125b0c71c9277f1e1deb57243') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
