INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10011095, 'RPU_30_100_A3', '엘크루 - 유량 [지역난방 수요처 공급계통]', '엘크루 - 유량', '엘크루', '[지역난방 수요처 공급계통]', '엘크루의 유량 계측 지점으로, 지역난방 수요처 공급계통의 순환/공급 유량을 감시합니다.', '계통 순환/공급 유량을 측정하여 수요 대응과 배관 상태를 판단하는 지표입니다.', '상승: 수요 급증 또는 제어밸브 과개도. 하강: 수요 급감·밸브 막힘·펌프 성능 저하 또는 배관 누설.', '1. 유량 현재값·추세 확인. 2. 수요·밸브 개도 확인. 3. 펌프 상태 확인. 4. 유량계 정상 여부 확인.', '수요·밸브 상태 확인 후 유로를 조정하고, 유량계 이상 시 교차 확인.', '유량 급감 지속 시 펌프·배관 막힘/누설 여부를 우선 점검하고 필요 시 유로 절체.', '[{"tag_name": "MM_RPU_30_100_A4", "description": "엘크루 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_30_100_A5", "description": "엘크루 - 적산열량 (DIFF)"}, {"tag_name": "RPU_30_100_A1", "description": "엘크루 - 공급온도"}, {"tag_name": "RPU_30_100_A2", "description": "엘크루 - 회수온도"}, {"tag_name": "RPU_30_100_A4", "description": "엘크루 - 적산유량"}, {"tag_name": "RPU_30_100_A5", "description": "엘크루 - 적산열량"}, {"tag_name": "RPU_30_100_A6", "description": "엘크루 - 압력"}, {"tag_name": "RPU_30_100_A7", "description": "엘크루 - 열량"}]'::jsonb, 'edecc2554a78c228c137dd2b60385d4dc0c4495fa83ce46514963f8de8c8ba2e') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10011096, 'RPU_30_100_A4', '엘크루 - 적산유량 [지역난방 수요처 공급계통]', '엘크루 - 적산유량', '엘크루', '[지역난방 수요처 공급계통]', '엘크루의 적산 계량 지점으로, 공급된 유량/열량의 누적값을 관리합니다.', '적산(유량/열량) 계량값으로, 수요처 공급량 정산과 계량 건전성 판단에 사용됩니다.', '정상 시 단조 증가. 급변·정지: 계량기 오차·펄스 누락, 역류/기포/이물질, 통신 지연에 따른 적산 누락 가능.', '1. 적산값 추세와 순시(유량/온도) 값 정합성 확인. 2. 계량기·통신 상태 확인. 3. 역류·기포·이물질 여부 확인.', '적산-순시 값 대조로 정합성 확인, 계량기/통신 점검. 이상 지속 시 계량 정비 담당 통보 및 대체 계량 검토.', '계량 정지·역행 발생 시 정산 영향 최소화를 위해 즉시 대체 계량 및 보정 절차 적용.', '[{"tag_name": "MM_RPU_30_100_A4", "description": "엘크루 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_30_100_A5", "description": "엘크루 - 적산열량 (DIFF)"}, {"tag_name": "RPU_30_100_A1", "description": "엘크루 - 공급온도"}, {"tag_name": "RPU_30_100_A2", "description": "엘크루 - 회수온도"}, {"tag_name": "RPU_30_100_A3", "description": "엘크루 - 유량"}, {"tag_name": "RPU_30_100_A5", "description": "엘크루 - 적산열량"}, {"tag_name": "RPU_30_100_A6", "description": "엘크루 - 압력"}, {"tag_name": "RPU_30_100_A7", "description": "엘크루 - 열량"}]'::jsonb, '516dce10c1bb6c44d2217b75f2377a6f29c93b304d90762d160b1b84d56c015c') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10011097, 'RPU_30_100_A5', '엘크루 - 적산열량 [지역난방 수요처 공급계통]', '엘크루 - 적산열량', '엘크루', '[지역난방 수요처 공급계통]', '엘크루의 적산 계량 지점으로, 공급된 유량/열량의 누적값을 관리합니다.', '적산(유량/열량) 계량값으로, 수요처 공급량 정산과 계량 건전성 판단에 사용됩니다.', '정상 시 단조 증가. 급변·정지: 계량기 오차·펄스 누락, 역류/기포/이물질, 통신 지연에 따른 적산 누락 가능.', '1. 적산값 추세와 순시(유량/온도) 값 정합성 확인. 2. 계량기·통신 상태 확인. 3. 역류·기포·이물질 여부 확인.', '적산-순시 값 대조로 정합성 확인, 계량기/통신 점검. 이상 지속 시 계량 정비 담당 통보 및 대체 계량 검토.', '계량 정지·역행 발생 시 정산 영향 최소화를 위해 즉시 대체 계량 및 보정 절차 적용.', '[{"tag_name": "MM_RPU_30_100_A4", "description": "엘크루 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_30_100_A5", "description": "엘크루 - 적산열량 (DIFF)"}, {"tag_name": "RPU_30_100_A1", "description": "엘크루 - 공급온도"}, {"tag_name": "RPU_30_100_A2", "description": "엘크루 - 회수온도"}, {"tag_name": "RPU_30_100_A3", "description": "엘크루 - 유량"}, {"tag_name": "RPU_30_100_A4", "description": "엘크루 - 적산유량"}, {"tag_name": "RPU_30_100_A6", "description": "엘크루 - 압력"}, {"tag_name": "RPU_30_100_A7", "description": "엘크루 - 열량"}]'::jsonb, 'f33c8c91fad056acffe57da64660fd84e2a81fe6dab110add52b98b26a946305') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10011098, 'RPU_30_100_A6', '엘크루 - 압력 [지역난방 수요처 공급계통]', '엘크루 - 압력', '엘크루', '[지역난방 수요처 공급계통]', '엘크루의 압력 계측 지점으로, 지역난방 수요처 공급계통의 압력 상태와 순환/공급 균형을 감시합니다.', '계통 압력을 측정하여 순환 상태와 부하 변화를 판단하는 핵심 지표입니다.', '상승: 부하측 밸브 급폐·수요 급감 또는 배관 저항 증가에 따른 압력 상승. 하강: 순환수 누설·펌프 성능 저하·흡입측 막힘에 따른 압력 저하.', '1. 압력 현재값·추세 확인. 2. 공급/회수 압력·차압 균형 확인. 3. 관련 펌프·밸브 상태 확인. 4. 통신상태(계측 신뢰성) 확인.', '부하측 밸브·수요 변화 확인 후 순환유량/개도를 단계적으로 조정. 펌프 제어 모드와 인버터·바이패스 상태 점검. 미해소 시 예비 펌프 절체 검토.', '고압 지속 시 부하 경감 후 정지 절차 검토(트립 예방). 저압 급강 시 저압 트립·공동현상에 유의하고 급수/보충수 계통을 회복.', '[{"tag_name": "MM_RPU_30_100_A4", "description": "엘크루 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_30_100_A5", "description": "엘크루 - 적산열량 (DIFF)"}, {"tag_name": "RPU_30_100_A1", "description": "엘크루 - 공급온도"}, {"tag_name": "RPU_30_100_A2", "description": "엘크루 - 회수온도"}, {"tag_name": "RPU_30_100_A3", "description": "엘크루 - 유량"}, {"tag_name": "RPU_30_100_A4", "description": "엘크루 - 적산유량"}, {"tag_name": "RPU_30_100_A5", "description": "엘크루 - 적산열량"}, {"tag_name": "RPU_30_100_A7", "description": "엘크루 - 열량"}]'::jsonb, '677e6e97577cd7b5d1e33816affc683641462871b61cb919b5de42362babe4e4') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
