INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (20010080, 'RPU_30_21_STS', '테크노밸리#4 - 통신상태 [지역난방 수요처 공급계통]', '테크노밸리#4 - 통신상태', '테크노밸리#4', '[지역난방 수요처 공급계통]', '테크노밸리#4의 통신 상태 감시 지점으로, 원격 계측(RPU)의 통신 건전성을 감시합니다.', '계측기 통신 상태를 나타내며, 값 신뢰성 판단의 기준이 됩니다.', '통신 두절(알람): RPU/네트워크 장애, 케이블·전원 이상, 현장 계측기 고장 또는 상위 수집 서버 장애.', '1. 통신 선로·전원 상태 확인. 2. RPU·게이트웨이 동작 상태 확인. 3. 해당 설비 계측값 신뢰성 교차 확인.', '통신 선로·전원과 RPU 상태를 확인하고 재접속·리셋. 미복구 시 계측 정비 담당에 통보.', '통신 두절 동안 해당 설비 계측값을 신뢰성 주의로 간주하고 관련 태그로 교차 판단.', '[{"tag_name": "MM_RPU_30_21_A4", "description": "테크노밸리#4 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_30_21_A5", "description": "테크노밸리#4 - 적산열량 (DIFF)"}, {"tag_name": "RPU_30_21_A1", "description": "테크노밸리#4 - 공급온도"}, {"tag_name": "RPU_30_21_A2", "description": "테크노밸리#4 - 회수온도"}, {"tag_name": "RPU_30_21_A3", "description": "테크노밸리#4 - 유량"}, {"tag_name": "RPU_30_21_A4", "description": "테크노밸리#4 - 적산유량"}, {"tag_name": "RPU_30_21_A5", "description": "테크노밸리#4 - 적산열량"}, {"tag_name": "RPU_30_21_A6", "description": "테크노밸리#4 - 압력"}]'::jsonb, '674cff502aae5faaee5c9768dce99b8d032c539603148095b4c02221471cfb7e') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10010561, 'RPU_30_22_A1', '테크노밸리#5-1 - 공급온도 [지역난방 수요처 공급계통]', '테크노밸리#5-1 - 공급온도', '테크노밸리#5-1', '[지역난방 수요처 공급계통]', '테크노밸리#5-1의 온도 계측 지점으로, 지역난방 수요처 공급계통의 열공급/회수 온도 상태를 감시합니다.', '열원 공급과 열교환 상태를 판단하는 온도 지표입니다.', '상승: 열원 과열·온도 제어 이상 또는 부하 급감에 따른 공급열 과잉. 하강: 열원 공급 부족·열교환기 성능 저하 또는 부하 급증.', '1. 온도 현재값·추세 확인. 2. 열원(보일러/열교환기) 운전 상태 확인. 3. 부하 변동 확인. 4. 온도 발신기 정상 여부 확인.', '열원 공급과 열교환 상태를 확인하고 제어 모드·설정값을 점검하여 열공급을 조정.', '온도 과상승 지속 시 열원 출력 경감 및 관련 계통 보호 조치. 과저하 시 공급 부족 원인을 우선 조치.', '[{"tag_name": "MM_RPU_30_22_A4", "description": "테크노밸리#5-1 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_30_22_A5", "description": "테크노밸리#5-1 - 적산열량 (DIFF)"}, {"tag_name": "RPU_30_22_A2", "description": "테크노밸리#5-1 - 회수온도"}, {"tag_name": "RPU_30_22_A3", "description": "테크노밸리#5-1 - 유량"}, {"tag_name": "RPU_30_22_A4", "description": "테크노밸리#5-1 - 적산유량"}, {"tag_name": "RPU_30_22_A5", "description": "테크노밸리#5-1 - 적산열량"}, {"tag_name": "RPU_30_22_A6", "description": "테크노밸리#5-1 - 압력"}, {"tag_name": "RPU_30_22_A7", "description": "테크노밸리#5-1 - 열량"}]'::jsonb, '97fca11f9d8f4b5de290740a2225ca7c713f514e872d1cbe16a73d37a5ef985e') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
