INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10010930, 'RPU_30_75_A6', '한우리아파트 - 압력 [지역난방 수요처 공급계통]', '한우리아파트 - 압력', '한우리아파트', '[지역난방 수요처 공급계통]', '한우리아파트의 압력 계측 지점으로, 지역난방 수요처 공급계통의 압력 상태와 순환/공급 균형을 감시합니다.', '계통 압력을 측정하여 순환 상태와 부하 변화를 판단하는 핵심 지표입니다.', '상승: 부하측 밸브 급폐·수요 급감 또는 배관 저항 증가에 따른 압력 상승. 하강: 순환수 누설·펌프 성능 저하·흡입측 막힘에 따른 압력 저하.', '1. 압력 현재값·추세 확인. 2. 공급/회수 압력·차압 균형 확인. 3. 관련 펌프·밸브 상태 확인. 4. 통신상태(계측 신뢰성) 확인.', '부하측 밸브·수요 변화 확인 후 순환유량/개도를 단계적으로 조정. 펌프 제어 모드와 인버터·바이패스 상태 점검. 미해소 시 예비 펌프 절체 검토.', '고압 지속 시 부하 경감 후 정지 절차 검토(트립 예방). 저압 급강 시 저압 트립·공동현상에 유의하고 급수/보충수 계통을 회복.', '[{"tag_name": "MM_RPU_30_75_A4", "description": "한우리아파트 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_30_75_A5", "description": "한우리아파트 - 적산열량 (DIFF)"}, {"tag_name": "RPU_30_75_A1", "description": "한우리아파트 - 공급온도"}, {"tag_name": "RPU_30_75_A2", "description": "한우리아파트 - 회수온도"}, {"tag_name": "RPU_30_75_A3", "description": "한우리아파트 - 유량"}, {"tag_name": "RPU_30_75_A4", "description": "한우리아파트 - 적산유량"}, {"tag_name": "RPU_30_75_A5", "description": "한우리아파트 - 적산열량"}, {"tag_name": "RPU_30_75_A7", "description": "한우리아파트 - 열량"}]'::jsonb, 'e2712f06a5a5f07b564179478d0b61e7b7e4383ef1f184d7f29691e973261e3b') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
