INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10010949, 'RPU_30_78_A4', '봉산휴먼시아2단지#1 - 적산유량 [지역난방 수요처 공급계통]', '봉산휴먼시아2단지#1 - 적산유량', '봉산휴먼시아2단지#1', '[지역난방 수요처 공급계통]', '봉산휴먼시아2단지#1의 적산 계량 지점으로, 공급된 유량/열량의 누적값을 관리합니다.', '적산(유량/열량) 계량값으로, 수요처 공급량 정산과 계량 건전성 판단에 사용됩니다.', '정상 시 단조 증가. 급변·정지: 계량기 오차·펄스 누락, 역류/기포/이물질, 통신 지연에 따른 적산 누락 가능.', '1. 적산값 추세와 순시(유량/온도) 값 정합성 확인. 2. 계량기·통신 상태 확인. 3. 역류·기포·이물질 여부 확인.', '적산-순시 값 대조로 정합성 확인, 계량기/통신 점검. 이상 지속 시 계량 정비 담당 통보 및 대체 계량 검토.', '계량 정지·역행 발생 시 정산 영향 최소화를 위해 즉시 대체 계량 및 보정 절차 적용.', '[{"tag_name": "MM_RPU_30_78_A4", "description": "봉산휴먼시아2단지#1 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_30_78_A5", "description": "봉산휴먼시아2단지#1 - 적산열량 (DIFF)"}, {"tag_name": "RPU_30_78_A1", "description": "봉산휴먼시아2단지#1 - 공급온도"}, {"tag_name": "RPU_30_78_A2", "description": "봉산휴먼시아2단지#1 - 회수온도"}, {"tag_name": "RPU_30_78_A3", "description": "봉산휴먼시아2단지#1 - 유량"}, {"tag_name": "RPU_30_78_A5", "description": "봉산휴먼시아2단지#1 - 적산열량"}, {"tag_name": "RPU_30_78_A6", "description": "봉산휴먼시아2단지#1 - 압력"}, {"tag_name": "RPU_30_78_A7", "description": "봉산휴먼시아2단지#1 - 열량"}]'::jsonb, '1b48270054d3df127a47aa9c3f7d11cd12206448d8af6d202fdceb3d485d25bd') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
