INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10010963, 'RPU_30_80_A4', '대덕국민체육센터 - 적산유량 [지역난방 수요처 공급계통]', '대덕국민체육센터 - 적산유량', '대덕국민체육센터', '[지역난방 수요처 공급계통]', '대덕국민체육센터의 적산 계량 지점으로, 공급된 유량/열량의 누적값을 관리합니다.', '적산(유량/열량) 계량값으로, 수요처 공급량 정산과 계량 건전성 판단에 사용됩니다.', '정상 시 단조 증가. 급변·정지: 계량기 오차·펄스 누락, 역류/기포/이물질, 통신 지연에 따른 적산 누락 가능.', '1. 적산값 추세와 순시(유량/온도) 값 정합성 확인. 2. 계량기·통신 상태 확인. 3. 역류·기포·이물질 여부 확인.', '적산-순시 값 대조로 정합성 확인, 계량기/통신 점검. 이상 지속 시 계량 정비 담당 통보 및 대체 계량 검토.', '계량 정지·역행 발생 시 정산 영향 최소화를 위해 즉시 대체 계량 및 보정 절차 적용.', '[{"tag_name": "MM_RPU_30_80_A4", "description": "대덕국민체육센터 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_30_80_A5", "description": "대덕국민체육센터 - 적산열량 (DIFF)"}, {"tag_name": "RPU_30_80_A1", "description": "대덕국민체육센터 - 공급온도"}, {"tag_name": "RPU_30_80_A2", "description": "대덕국민체육센터 - 회수온도"}, {"tag_name": "RPU_30_80_A3", "description": "대덕국민체육센터 - 유량"}, {"tag_name": "RPU_30_80_A5", "description": "대덕국민체육센터 - 적산열량"}, {"tag_name": "RPU_30_80_A6", "description": "대덕국민체육센터 - 압력"}, {"tag_name": "RPU_30_80_A7", "description": "대덕국민체육센터 - 열량"}]'::jsonb, '91199da9f894b50c466cdd6d1e26a0e4214c64ee4e924bd2533e660cf4e3c5af') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10010964, 'RPU_30_80_A5', '대덕국민체육센터 - 적산열량 [지역난방 수요처 공급계통]', '대덕국민체육센터 - 적산열량', '대덕국민체육센터', '[지역난방 수요처 공급계통]', '대덕국민체육센터의 적산 계량 지점으로, 공급된 유량/열량의 누적값을 관리합니다.', '적산(유량/열량) 계량값으로, 수요처 공급량 정산과 계량 건전성 판단에 사용됩니다.', '정상 시 단조 증가. 급변·정지: 계량기 오차·펄스 누락, 역류/기포/이물질, 통신 지연에 따른 적산 누락 가능.', '1. 적산값 추세와 순시(유량/온도) 값 정합성 확인. 2. 계량기·통신 상태 확인. 3. 역류·기포·이물질 여부 확인.', '적산-순시 값 대조로 정합성 확인, 계량기/통신 점검. 이상 지속 시 계량 정비 담당 통보 및 대체 계량 검토.', '계량 정지·역행 발생 시 정산 영향 최소화를 위해 즉시 대체 계량 및 보정 절차 적용.', '[{"tag_name": "MM_RPU_30_80_A4", "description": "대덕국민체육센터 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_30_80_A5", "description": "대덕국민체육센터 - 적산열량 (DIFF)"}, {"tag_name": "RPU_30_80_A1", "description": "대덕국민체육센터 - 공급온도"}, {"tag_name": "RPU_30_80_A2", "description": "대덕국민체육센터 - 회수온도"}, {"tag_name": "RPU_30_80_A3", "description": "대덕국민체육센터 - 유량"}, {"tag_name": "RPU_30_80_A4", "description": "대덕국민체육센터 - 적산유량"}, {"tag_name": "RPU_30_80_A6", "description": "대덕국민체육센터 - 압력"}, {"tag_name": "RPU_30_80_A7", "description": "대덕국민체육센터 - 열량"}]'::jsonb, 'bb566d24896f9e8bb7ea4aa854c0633a1a944c26b14269d8d00f9b7143a50556') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10010965, 'RPU_30_80_A6', '대덕국민체육센터 - 압력 [지역난방 수요처 공급계통]', '대덕국민체육센터 - 압력', '대덕국민체육센터', '[지역난방 수요처 공급계통]', '대덕국민체육센터의 압력 계측 지점으로, 지역난방 수요처 공급계통의 압력 상태와 순환/공급 균형을 감시합니다.', '계통 압력을 측정하여 순환 상태와 부하 변화를 판단하는 핵심 지표입니다.', '상승: 부하측 밸브 급폐·수요 급감 또는 배관 저항 증가에 따른 압력 상승. 하강: 순환수 누설·펌프 성능 저하·흡입측 막힘에 따른 압력 저하.', '1. 압력 현재값·추세 확인. 2. 공급/회수 압력·차압 균형 확인. 3. 관련 펌프·밸브 상태 확인. 4. 통신상태(계측 신뢰성) 확인.', '부하측 밸브·수요 변화 확인 후 순환유량/개도를 단계적으로 조정. 펌프 제어 모드와 인버터·바이패스 상태 점검. 미해소 시 예비 펌프 절체 검토.', '고압 지속 시 부하 경감 후 정지 절차 검토(트립 예방). 저압 급강 시 저압 트립·공동현상에 유의하고 급수/보충수 계통을 회복.', '[{"tag_name": "MM_RPU_30_80_A4", "description": "대덕국민체육센터 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_30_80_A5", "description": "대덕국민체육센터 - 적산열량 (DIFF)"}, {"tag_name": "RPU_30_80_A1", "description": "대덕국민체육센터 - 공급온도"}, {"tag_name": "RPU_30_80_A2", "description": "대덕국민체육센터 - 회수온도"}, {"tag_name": "RPU_30_80_A3", "description": "대덕국민체육센터 - 유량"}, {"tag_name": "RPU_30_80_A4", "description": "대덕국민체육센터 - 적산유량"}, {"tag_name": "RPU_30_80_A5", "description": "대덕국민체육센터 - 적산열량"}, {"tag_name": "RPU_30_80_A7", "description": "대덕국민체육센터 - 열량"}]'::jsonb, '7387e7e9b6737e5e2b9cd9b31ea7e81903b02f53bc1c8e2a2ba77ef087353022') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
