INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10011042, 'RPU_30_91_A6', '엑슬루 - 압력 [지역난방 수요처 공급계통]', '엑슬루 - 압력', '엑슬루', '[지역난방 수요처 공급계통]', '엑슬루의 압력 계측 지점으로, 지역난방 수요처 공급계통의 압력 상태와 순환/공급 균형을 감시합니다.', '계통 압력을 측정하여 순환 상태와 부하 변화를 판단하는 핵심 지표입니다.', '상승: 부하측 밸브 급폐·수요 급감 또는 배관 저항 증가에 따른 압력 상승. 하강: 순환수 누설·펌프 성능 저하·흡입측 막힘에 따른 압력 저하.', '1. 압력 현재값·추세 확인. 2. 공급/회수 압력·차압 균형 확인. 3. 관련 펌프·밸브 상태 확인. 4. 통신상태(계측 신뢰성) 확인.', '부하측 밸브·수요 변화 확인 후 순환유량/개도를 단계적으로 조정. 펌프 제어 모드와 인버터·바이패스 상태 점검. 미해소 시 예비 펌프 절체 검토.', '고압 지속 시 부하 경감 후 정지 절차 검토(트립 예방). 저압 급강 시 저압 트립·공동현상에 유의하고 급수/보충수 계통을 회복.', '[{"tag_name": "MM_RPU_30_91_A4", "description": "엑슬루 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_30_91_A5", "description": "엑슬루 - 적산열량 (DIFF)"}, {"tag_name": "RPU_30_91_A1", "description": "엑슬루 - 공급온도"}, {"tag_name": "RPU_30_91_A2", "description": "엑슬루 - 회수온도"}, {"tag_name": "RPU_30_91_A3", "description": "엑슬루 - 유량"}, {"tag_name": "RPU_30_91_A4", "description": "엑슬루 - 적산유량"}, {"tag_name": "RPU_30_91_A5", "description": "엑슬루 - 적산열량"}, {"tag_name": "RPU_30_91_A7", "description": "엑슬루 - 열량"}]'::jsonb, 'e350ab5da48d748fc64e2d3fd212b4e09c438c6c7695d395d32f372d79cd87c8') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10011043, 'RPU_30_91_A7', '엑슬루 - 열량 [지역난방 수요처 공급계통]', '엑슬루 - 열량', '엑슬루', '[지역난방 수요처 공급계통]', '엑슬루의 적산 계량 지점으로, 공급된 유량/열량의 누적값을 관리합니다.', '적산(유량/열량) 계량값으로, 수요처 공급량 정산과 계량 건전성 판단에 사용됩니다.', '정상 시 단조 증가. 급변·정지: 계량기 오차·펄스 누락, 역류/기포/이물질, 통신 지연에 따른 적산 누락 가능.', '1. 적산값 추세와 순시(유량/온도) 값 정합성 확인. 2. 계량기·통신 상태 확인. 3. 역류·기포·이물질 여부 확인.', '적산-순시 값 대조로 정합성 확인, 계량기/통신 점검. 이상 지속 시 계량 정비 담당 통보 및 대체 계량 검토.', '계량 정지·역행 발생 시 정산 영향 최소화를 위해 즉시 대체 계량 및 보정 절차 적용.', '[{"tag_name": "MM_RPU_30_91_A4", "description": "엑슬루 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_30_91_A5", "description": "엑슬루 - 적산열량 (DIFF)"}, {"tag_name": "RPU_30_91_A1", "description": "엑슬루 - 공급온도"}, {"tag_name": "RPU_30_91_A2", "description": "엑슬루 - 회수온도"}, {"tag_name": "RPU_30_91_A3", "description": "엑슬루 - 유량"}, {"tag_name": "RPU_30_91_A4", "description": "엑슬루 - 적산유량"}, {"tag_name": "RPU_30_91_A5", "description": "엑슬루 - 적산열량"}, {"tag_name": "RPU_30_91_A6", "description": "엑슬루 - 압력"}]'::jsonb, '5be9526b42c1526dcc87604458c3132bbd78b27f5ac51fc24bcfe735a9dae9c0') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (20010149, 'RPU_30_91_STS', '엑슬루 - 통신상태 [지역난방 수요처 공급계통]', '엑슬루 - 통신상태', '엑슬루', '[지역난방 수요처 공급계통]', '엑슬루의 통신 상태 감시 지점으로, 원격 계측(RPU)의 통신 건전성을 감시합니다.', '계측기 통신 상태를 나타내며, 값 신뢰성 판단의 기준이 됩니다.', '통신 두절(알람): RPU/네트워크 장애, 케이블·전원 이상, 현장 계측기 고장 또는 상위 수집 서버 장애.', '1. 통신 선로·전원 상태 확인. 2. RPU·게이트웨이 동작 상태 확인. 3. 해당 설비 계측값 신뢰성 교차 확인.', '통신 선로·전원과 RPU 상태를 확인하고 재접속·리셋. 미복구 시 계측 정비 담당에 통보.', '통신 두절 동안 해당 설비 계측값을 신뢰성 주의로 간주하고 관련 태그로 교차 판단.', '[{"tag_name": "MM_RPU_30_91_A4", "description": "엑슬루 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_30_91_A5", "description": "엑슬루 - 적산열량 (DIFF)"}, {"tag_name": "RPU_30_91_A1", "description": "엑슬루 - 공급온도"}, {"tag_name": "RPU_30_91_A2", "description": "엑슬루 - 회수온도"}, {"tag_name": "RPU_30_91_A3", "description": "엑슬루 - 유량"}, {"tag_name": "RPU_30_91_A4", "description": "엑슬루 - 적산유량"}, {"tag_name": "RPU_30_91_A5", "description": "엑슬루 - 적산열량"}, {"tag_name": "RPU_30_91_A6", "description": "엑슬루 - 압력"}]'::jsonb, '2f4ece9ea0962eafb61987c8ad168f555c1c9441d8879cb3fc5850d46b4444fa') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10011044, 'RPU_30_92_A1', '디티비안W - 공급온도 [지역난방 수요처 공급계통]', '디티비안W - 공급온도', '디티비안W', '[지역난방 수요처 공급계통]', '디티비안W의 온도 계측 지점으로, 지역난방 수요처 공급계통의 열공급/회수 온도 상태를 감시합니다.', '열원 공급과 열교환 상태를 판단하는 온도 지표입니다.', '상승: 열원 과열·온도 제어 이상 또는 부하 급감에 따른 공급열 과잉. 하강: 열원 공급 부족·열교환기 성능 저하 또는 부하 급증.', '1. 온도 현재값·추세 확인. 2. 열원(보일러/열교환기) 운전 상태 확인. 3. 부하 변동 확인. 4. 온도 발신기 정상 여부 확인.', '열원 공급과 열교환 상태를 확인하고 제어 모드·설정값을 점검하여 열공급을 조정.', '온도 과상승 지속 시 열원 출력 경감 및 관련 계통 보호 조치. 과저하 시 공급 부족 원인을 우선 조치.', '[{"tag_name": "MM_RPU_30_92_A4", "description": "디티비안W - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_30_92_A5", "description": "디티비안W - 적산열량 (DIFF)"}, {"tag_name": "RPU_30_92_A2", "description": "디티비안W - 회수온도"}, {"tag_name": "RPU_30_92_A3", "description": "디티비안W - 유량"}, {"tag_name": "RPU_30_92_A4", "description": "디티비안W - 적산유량"}, {"tag_name": "RPU_30_92_A5", "description": "디티비안W - 적산열량"}, {"tag_name": "RPU_30_92_A6", "description": "디티비안W - 압력"}, {"tag_name": "RPU_30_92_A7", "description": "디티비안W - 열량"}]'::jsonb, 'dd937acb50c397651bc508db1597636de77df4f235b14e6470003825837bb68a') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
