INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (20010023, 'RPU_9_11_B_STS', '현대 아울렛BYPASS - 통신상태 [지역난방 수요처 공급계통]', '현대 아울렛BYPASS - 통신상태', '현대 아울렛BYPASS', '[지역난방 수요처 공급계통]', '현대 아울렛BYPASS의 통신 상태 감시 지점으로, 원격 계측(RPU)의 통신 건전성을 감시합니다.', '계측기 통신 상태를 나타내며, 값 신뢰성 판단의 기준이 됩니다.', '통신 두절(알람): RPU/네트워크 장애, 케이블·전원 이상, 현장 계측기 고장 또는 상위 수집 서버 장애.', '1. 통신 선로·전원 상태 확인. 2. RPU·게이트웨이 동작 상태 확인. 3. 해당 설비 계측값 신뢰성 교차 확인.', '통신 선로·전원과 RPU 상태를 확인하고 재접속·리셋. 미복구 시 계측 정비 담당에 통보.', '통신 두절 동안 해당 설비 계측값을 신뢰성 주의로 간주하고 관련 태그로 교차 판단.', '[{"tag_name": "MM_RPU_9_11_B_A4", "description": "현대 아울렛BYPASS - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_9_11_B_A5", "description": "현대 아울렛BYPASS - 적산열량 (DIFF)"}, {"tag_name": "RPU_9_11_B_A1", "description": "현대 아울렛BYPASS - 공급온도"}, {"tag_name": "RPU_9_11_B_A2", "description": "현대 아울렛BYPASS - 회수온도"}, {"tag_name": "RPU_9_11_B_A3", "description": "현대 아울렛BYPASS - 유량"}, {"tag_name": "RPU_9_11_B_A4", "description": "현대 아울렛BYPASS - 적산유량"}, {"tag_name": "RPU_9_11_B_A5", "description": "현대 아울렛BYPASS - 적산열량"}, {"tag_name": "RPU_9_11_B_A6", "description": "현대 아울렛BYPASS - 압력"}]'::jsonb, 'fb7aaf21eff4a6d2f219643fa51a74f7c5b778a8cb4f3becd903f99893452e74') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
