INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10010169, 'RPU_9_11_W_A1', '현대아울렛 - 공급온도 [지역난방 수요처 공급계통]', '현대아울렛 - 공급온도', '현대아울렛', '[지역난방 수요처 공급계통]', '현대아울렛의 온도 계측 지점으로, 지역난방 수요처 공급계통의 열공급/회수 온도 상태를 감시합니다.', '열원 공급과 열교환 상태를 판단하는 온도 지표입니다.', '상승: 열원 과열·온도 제어 이상 또는 부하 급감에 따른 공급열 과잉. 하강: 열원 공급 부족·열교환기 성능 저하 또는 부하 급증.', '1. 온도 현재값·추세 확인. 2. 열원(보일러/열교환기) 운전 상태 확인. 3. 부하 변동 확인. 4. 온도 발신기 정상 여부 확인.', '열원 공급과 열교환 상태를 확인하고 제어 모드·설정값을 점검하여 열공급을 조정.', '온도 과상승 지속 시 열원 출력 경감 및 관련 계통 보호 조치. 과저하 시 공급 부족 원인을 우선 조치.', '[{"tag_name": "MM_RPU_9_11_A4", "description": "현대아울렛 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_9_11_A5", "description": "현대아울렛 - 적산열량 (DIFF)"}, {"tag_name": "MM_RPU_9_11_W_A4", "description": "현대아울렛 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_9_11_W_A5", "description": "현대아울렛 - 적산열량 (DIFF)"}, {"tag_name": "RPU_9_11_A1", "description": "현대아울렛 - 공급온도"}, {"tag_name": "RPU_9_11_A2", "description": "현대아울렛 - 회수온도"}, {"tag_name": "RPU_9_11_A3", "description": "현대아울렛 - 유량"}, {"tag_name": "RPU_9_11_A4", "description": "현대아울렛 - 적산유량"}]'::jsonb, 'd0f9853e6600ba0d6f58978744f78f91b18c6160865ff48cd8cd6fc705383b05') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
