INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10010171, 'RPU_9_11_W_A3', '현대아울렛 - 유량 [지역난방 수요처 공급계통]', '현대아울렛 - 유량', '현대아울렛', '[지역난방 수요처 공급계통]', '현대아울렛의 유량 계측 지점으로, 지역난방 수요처 공급계통의 순환/공급 유량을 감시합니다.', '계통 순환/공급 유량을 측정하여 수요 대응과 배관 상태를 판단하는 지표입니다.', '상승: 수요 급증 또는 제어밸브 과개도. 하강: 수요 급감·밸브 막힘·펌프 성능 저하 또는 배관 누설.', '1. 유량 현재값·추세 확인. 2. 수요·밸브 개도 확인. 3. 펌프 상태 확인. 4. 유량계 정상 여부 확인.', '수요·밸브 상태 확인 후 유로를 조정하고, 유량계 이상 시 교차 확인.', '유량 급감 지속 시 펌프·배관 막힘/누설 여부를 우선 점검하고 필요 시 유로 절체.', '[{"tag_name": "MM_RPU_9_11_A4", "description": "현대아울렛 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_9_11_A5", "description": "현대아울렛 - 적산열량 (DIFF)"}, {"tag_name": "MM_RPU_9_11_W_A4", "description": "현대아울렛 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_9_11_W_A5", "description": "현대아울렛 - 적산열량 (DIFF)"}, {"tag_name": "RPU_9_11_A1", "description": "현대아울렛 - 공급온도"}, {"tag_name": "RPU_9_11_A2", "description": "현대아울렛 - 회수온도"}, {"tag_name": "RPU_9_11_A3", "description": "현대아울렛 - 유량"}, {"tag_name": "RPU_9_11_A4", "description": "현대아울렛 - 적산유량"}]'::jsonb, '9866e4d153268bb49f2756d1cf1f7ba2f4956ca1c52f36c974469bc8b182fc5f') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO tag_description (tag_id, tag_name, description, tag_nm, tag_rmk, tag_desc, equipment_description, tag_description, value_change_meaning, key_check_points, action_guidance, failure_guidance, related_tags, content_hash) VALUES (10010172, 'RPU_9_11_W_A4', '현대아울렛 - 적산유량 [지역난방 수요처 공급계통]', '현대아울렛 - 적산유량', '현대아울렛', '[지역난방 수요처 공급계통]', '현대아울렛의 적산 계량 지점으로, 공급된 유량/열량의 누적값을 관리합니다.', '적산(유량/열량) 계량값으로, 수요처 공급량 정산과 계량 건전성 판단에 사용됩니다.', '정상 시 단조 증가. 급변·정지: 계량기 오차·펄스 누락, 역류/기포/이물질, 통신 지연에 따른 적산 누락 가능.', '1. 적산값 추세와 순시(유량/온도) 값 정합성 확인. 2. 계량기·통신 상태 확인. 3. 역류·기포·이물질 여부 확인.', '적산-순시 값 대조로 정합성 확인, 계량기/통신 점검. 이상 지속 시 계량 정비 담당 통보 및 대체 계량 검토.', '계량 정지·역행 발생 시 정산 영향 최소화를 위해 즉시 대체 계량 및 보정 절차 적용.', '[{"tag_name": "MM_RPU_9_11_A4", "description": "현대아울렛 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_9_11_A5", "description": "현대아울렛 - 적산열량 (DIFF)"}, {"tag_name": "MM_RPU_9_11_W_A4", "description": "현대아울렛 - 적산유량 (DIFF)"}, {"tag_name": "MM_RPU_9_11_W_A5", "description": "현대아울렛 - 적산열량 (DIFF)"}, {"tag_name": "RPU_9_11_A1", "description": "현대아울렛 - 공급온도"}, {"tag_name": "RPU_9_11_A2", "description": "현대아울렛 - 회수온도"}, {"tag_name": "RPU_9_11_A3", "description": "현대아울렛 - 유량"}, {"tag_name": "RPU_9_11_A4", "description": "현대아울렛 - 적산유량"}]'::jsonb, '3e0c8dc453c2559ffd3396182cfa4477eb2dd1fdffc337399a9b1203f191cc64') ON CONFLICT (tag_id) DO UPDATE SET tag_name=EXCLUDED.tag_name, description=EXCLUDED.description, tag_nm=EXCLUDED.tag_nm, tag_rmk=EXCLUDED.tag_rmk, tag_desc=EXCLUDED.tag_desc, equipment_description=EXCLUDED.equipment_description, tag_description=EXCLUDED.tag_description, value_change_meaning=EXCLUDED.value_change_meaning, key_check_points=EXCLUDED.key_check_points, action_guidance=EXCLUDED.action_guidance, failure_guidance=EXCLUDED.failure_guidance, related_tags=EXCLUDED.related_tags, content_hash=EXCLUDED.content_hash, updated_at=NOW();
